cypress_script:
describe('API endpoint documentation list', () => {
  it('should display the API documentation correctly', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('header').should('be.visible');
    cy.get('section#form').contains('APIs List for practice').should('be.visible');
    cy.get('a[href="https://automationexercise.com/api/productsList"]').should('be.visible');
  });
  it('should not navigate away when an invalid action is performed', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('a[href="#collapse1"]').click();
    cy.url().should('eq', 'https://automationexercise.com/api_list');
    cy.get('section#form').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';
test.describe('API endpoint documentation list', () => {
  test('should display the API documentation correctly', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await expect(page.locator('header')).toBeVisible();
    await expect(page.locator('section#form').locator('text=APIs List for practice')).toBeVisible();
    await expect(page.locator('a[href="https://automationexercise.com/api/productsList"]').first()).toBeVisible();
  });
  test('should not navigate away when an invalid action is performed', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await page.click('a[href="#collapse1"]');
    await expect(page).toHaveURL('https://automationexercise.com/api_list');
    await expect(page.locator('section#form')).toBeVisible();
  });
});
